CREATE TABLE ingest.candidate (
    candidate_id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    entity_type text NOT NULL,
    natural_key character(32) NOT NULL,
    university_name text,
    payload jsonb NOT NULL,
    page_id uuid,
    source_url text NOT NULL,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    extractor text NOT NULL,
    model text,
    prompt_version text,
    confidence real,
    checks jsonb DEFAULT '[]'::jsonb NOT NULL,
    proposed_status text NOT NULL,
    decision text NOT NULL,
    reject_reason text,
    matched_entity_id text,
    action text,
    diff jsonb DEFAULT '[]'::jsonb NOT NULL,
    reviewer text,
    reviewed_at timestamp with time zone,
    review_note text,
    release_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    qa_sample boolean DEFAULT false NOT NULL,
    qa_result text,
    CONSTRAINT candidate_action_check CHECK ((action = ANY (ARRAY['insert'::text, 'enrich'::text, 'propose'::text, 'noop'::text]))),
    CONSTRAINT candidate_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)))),
    CONSTRAINT candidate_decision_check CHECK ((decision = ANY (ARRAY['auto_accept'::text, 'needs_review'::text, 'rejected'::text, 'human_approved'::text, 'human_rejected'::text]))),
    CONSTRAINT candidate_entity_type_check CHECK ((entity_type = ANY (ARRAY['university'::text, 'professor'::text, 'program'::text, 'scholarship'::text, 'publication'::text]))),
    CONSTRAINT candidate_extractor_check CHECK ((extractor = ANY (ARRAY['css'::text, 'llm'::text, 'api'::text, 'manual'::text]))),
    CONSTRAINT candidate_proposed_status_check CHECK ((proposed_status = ANY (ARRAY['verified'::text, 'needs_review'::text, 'unverified'::text, 'outdated'::text]))),
    CONSTRAINT candidate_qa_result_check CHECK (((qa_result IS NULL) OR (qa_result = ANY (ARRAY['ok'::text, 'error'::text]))))
);


