--
-- Name: current_candidate; Type: VIEW; Schema: ingest; Owner: pipeline
--

CREATE VIEW ingest.current_candidate AS
 WITH run_rank AS (
         SELECT c_1.university_name,
            c_1.entity_type,
            c_1.run_id,
            max(r.started_at) AS started_at
           FROM (ingest.candidate c_1
             JOIN ingest.run r USING (run_id))
          GROUP BY c_1.university_name, c_1.entity_type, c_1.run_id
        ), newest AS (
         SELECT DISTINCT ON (run_rank.university_name, run_rank.entity_type) run_rank.university_name,
            run_rank.entity_type,
            run_rank.run_id
           FROM run_rank
          ORDER BY run_rank.university_name, run_rank.entity_type, run_rank.started_at DESC, run_rank.run_id
        )
 SELECT c.candidate_id,
    c.run_id,
    c.entity_type,
    c.natural_key,
    c.university_name,
    c.payload,
    c.page_id,
    c.source_url,
    c.evidence,
    c.extractor,
    c.model,
    c.prompt_version,
    c.confidence,
    c.checks,
    c.proposed_status,
    c.decision,
    c.reject_reason,
    c.matched_entity_id,
    c.action,
    c.diff,
    c.reviewer,
    c.reviewed_at,
    c.review_note,
    c.release_id,
    c.created_at,
    c.qa_sample,
    c.qa_result
   FROM (ingest.candidate c
     JOIN newest n ON (((n.run_id = c.run_id) AND (n.entity_type = c.entity_type) AND (NOT (n.university_name IS DISTINCT FROM c.university_name)))));


