    "logoUrl" text,
    "dataStatus" text DEFAULT 'unverified'::text NOT NULL,
    "dataSource" text,
    "applicationUrl" text,
    "applicationFee" text,
    "applicationDeadline" text,
    "scholarshipUrl" text,
    "scholarshipDeadline" text,
    "verifiedAt" timestamp(3) without time zone,
    "verificationStatus" text DEFAULT 'UNVERIFIED'::text NOT NULL,
    "lastCheckedAt" timestamp(3) without time zone,
    confidence double precision,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL
);


ALTER TABLE public."University" OWNER TO pipeline;

